preConditionHook:
// EL: upBodies/downBodies cleared by any failing pair over 0..trendBars-1,
// where the pair test is maxlist(o[i], c[i]) vs maxlist(o[i+1], c[i+1]) and
// the same on minlist (lowercase as the feature register writes it). All-of-N, written as
// TrendingHighsAndLows writes it: start true, let a failing pair clear it, so
// a tie on either body edge fails BOTH sides.
//
// maxlist/minlist are ACCEPTED in EL_FEATURES only for selection among
// tick-grid PRICE operands. These operands are raw opens and closes, so any two
// of them are equal or differ by at least a tick -- 1e9-1e11x the 2.22e-12
// relational tolerance -- and whether maxlist carries that tolerance cannot
// change the selection. The plain C++ comparisons here stand in for it, the
// same substitution Barbwire makes.
//
// Every scratch value is a declared local, not a hook-scope declaration, so a
// second placement of this rule gets its own prefixed copy.
upBodies = true;
downBodies = true;
for (ii = 0; ii < (int)trendBars; ++ii) {
    topNow = open[ii];
    if (close[ii] > topNow) topNow = close[ii];
    botNow = open[ii];
    if (close[ii] < botNow) botNow = close[ii];
    topPrev = open[ii + 1];
    if (close[ii + 1] > topPrev) topPrev = close[ii + 1];
    botPrev = open[ii + 1];
    if (close[ii + 1] < botPrev) botPrev = close[ii + 1];
    if (el_le(topNow, topPrev) || el_le(botNow, botPrev)) upBodies = false;
    if (el_ge(topNow, topPrev) || el_ge(botNow, botPrev)) downBodies = false;
}
